package com.devflux.deenone.features.hajj.data;

import com.devflux.deenone.features.hajj.model.HajjHistoryCardItem;

import java.util.ArrayList;
import java.util.List;

public class HajjAcceptanceContentRepository {

    public static List<HajjHistoryCardItem> getAcceptanceCards() {
        List<HajjHistoryCardItem> list = new ArrayList<>();

        // 1. ঈমান ও আমলে দৃঢ়তা সৃষ্টি হওয়া
        list.add(new HajjHistoryCardItem(
            1,
            "ঈমান ও আমলে দৃঢ়তা সৃষ্টি হওয়া",
            "Steadfastness in Faith and Deeds",
            "পার্থিবতা ও দুনিয়া-সংগ বিষয়-আশয়ের প্রতি অনীহা তৈরি হওয়া এবং আখিরাতের প্রতি আগ্রহ বৃদ্ধি পাওয়া...",
            "Developing detachment from fleeting worldly pursuits and increasing longing for the Hereafter...",
            "পার্থিবতা ও দুনিয়া-সংগ বিষয়-আশয়ের প্রতি অনীহা তৈরি হওয়া এবং আখিরাতের অনন্ত জীবনের প্রতি গভীর আকর্ষণ সৃষ্টি হওয়া মাবরুর হজের অন্যতম প্রধান লক্ষণ।\n\nপ্রখ্যাত তাবেয়ি ইমাম হাসান আল-বসরী (রহ.)-কে মাবরুর হজের লক্ষণ সম্পর্কে জিজ্ঞেস করা হলে তিনি বলেন:\n'হজের পর হাজী সাহেব এমন অবস্থায় ফিরবেন যে, তিনি পার্থিব জীবনের মোহের প্রতি উদাসীন হবেন এবং পরকালের জীবনের প্রতি আগ্রহী ও একনিষ্ঠ হবেন।' অর্থাৎ হজের পর তার নামাজ, রোজা, আখলাক ও চরিত্র পূর্বের তুলনায় বহুগুণ উন্নত ও দৃঢ় হবে।",
            "Detachment from temporary worldly temptations and developing a profound devotion to the Hereafter is one of the primary signs of an accepted Hajj (Hajj Mabrur).\n\nWhen the eminent Tabi'i Imam Hasan al-Basri (may Allah have mercy on him) was asked about the sign of an accepted Hajj, he replied:\n'It is that the pilgrim returns having turned away from the worldly life, longing eagerly for the Hereafter.' In other words, their prayers, fasting, morality, and God-consciousness become significantly more steadfast and steadfast than before."
        ));

        // 2. হজ পূর্ব জীবন
        list.add(new HajjHistoryCardItem(
            2,
            "হজ পূর্ব জীবন",
            "Transformation from Pre-Hajj Life",
            "হজ্জ-পূর্ব জীবনে যেসব পাপ ও অন্যায়ের সংলগ্নতা ছিল, হজের পর তা থেকে চিরতরে ফিরে আসা...",
            "Abandoning all past sins and transgressions of pre-Hajj life, beginning a purified new chapter...",
            "হজ্জ-পূর্ব জীবনে যেসব পাপ ও অন্যায়ের সংলগ্নতা বা অভ্যস্ততা ছিল, হজের পর তা থেকে চিরতরে ফিরে এসে এক নতুন ও নিষ্কলুষ জীবনের সূচনা করা।\n\nহজ হলো আত্মশুদ্ধি ও নবজন্মের মহাসুযোগ। রাসূলুল্লাহ (ﷺ) ইরশাদ করেছেন:\n'যে ব্যক্তি আল্লাহর সন্তুষ্টির উদ্দেশ্যে হজ করল এবং কোনো অশ্লীল কাজ ও পাপাচার করল না, সে নিষ্পাপ অবস্থায় ফিরে এল যেমন তার মা তাকে জন্ম দিয়েছিলেন।' (সহীহ বুখারী: ১৫২১)\nঅতএব, পূর্বের বদ-অভ্যাস, হারাম উপার্জন, মিথ্যা ও গাফিলতি পরিহার করে দ্বীনি জিন্দেগিতে অটল থাকাই কবুল হজের প্রত্যক্ষ প্রমাণ।",
            "Completely abandoning the sins, injustices, and bad habits that existed in one's pre-Hajj life, inaugurating a pure, righteous chapter of life.\n\nHajj is a supreme milestone for spiritual rebirth and purification. The Messenger of Allah (ﷺ) said:\n'Whoever performs Hajj for the sake of Allah and does not commit obscenity or sins will return as free from sin as the day his mother gave birth to him.' (Sahih al-Bukhari: 1521)\nTherefore, leaving behind past misconduct, illicit earnings, and heedlessness to remain firmly upon righteous conduct is clear evidence of an accepted Hajj."
        ));

        // 3. হজ সম্পাদনের পর কৃত আমলকে অল্প মনে করা
        list.add(new HajjHistoryCardItem(
            3,
            "হজ সম্পাদনের পর কৃত আমলকে অল্প মনে করা",
            "Considering Deeds Modest After Performing Hajj",
            "কেননা মানুষ যত আমলই করুক না-কেন আল্লাহর অসীম করুণা ও বড়ত্বের সামনে তা নিতান্তই সামান্য...",
            "For however many deeds a human performs, before Allah's boundless grace and majesty it is humble...",
            "কেননা মানুষ যত আমলই করুক না-কেন আল্লাহর অসীম করুণা, নিয়ামত ও মহান মর্যাদার সামনে তা নিতান্তই সামান্য।\n\nহজ সম্পাদন করার পর কখনো আত্মতুষ্টি বা গর্ববোধ (রিয়া ও উজুব) আনা যাবে না; বরং ভাবতে হবে—আল্লাহ রাব্বুল আলামিন তাঁর মেহেরবানিতে আমায় তাঁর পবিত্র ঘরে যাওয়ার সুযোগ দিয়েছেন, অথচ আমি তাঁর উপযুক্ত ইবাদত করতে পারিনি। এই বিনয় ও নিজের আমলকে সামান্য মনে করার মানসিকতাই আল্লাহ তা'আলার দরবারে বান্দার মর্যাদা বহুগুণ বাড়িয়ে দেয়।",
            "No matter how many deeds a servant accomplishes, compared to the boundless mercy, blessings, and majesty of Allah, they remain modest and humble.\n\nAfter completing Hajj, one must never succumb to self-righteousness, vanity, or pride (Ujub). Instead, one should reflect: 'Allah in His infinite grace permitted me to visit His Sacred House, yet my worship falls far short of His majesty.' This profound humility and viewing one's own righteous deeds as modest elevates the servant's status in the court of Allah."
        ));

        // 4. আমল কবুল না হওয়ার ভয় করা
        list.add(new HajjHistoryCardItem(
            4,
            "আমল কবুল না হওয়ার ভয় করা",
            "Fear of Deeds Not Being Accepted",
            "সাহাবায়ে কেরাম (রাদি আল্লাহু আনহুম) আমল করার পর তা কবুল হলো কি না সে বিষয়ে সর্বদা ভীত থাকতেন...",
            "The noble Companions (may Allah be pleased with them) constantly feared whether their deeds were accepted...",
            "সাহাবায়ে কেরাম (রাদি আল্লাহু আনহুম) আমল করার পর তা কবুল হলো কি না সে বিষয়ে সর্বদা অন্তরে ভয় ও সতর্কতা পোষণ করতেন।\n\nপবিত্র কুরআনে আল্লাহ তাআলা খাঁটি মুমিনদের প্রশংসা করে বলেন:\n'আর যারা যা কিছু দান করে তা ভীত-সন্ত্রস্ত অন্তরে করে, কারণ তারা তাদের রবের দিকে ফিরে যাবে।' (সূরা আল-মুমিনূন: ৬০)\nআম্মাজান আয়েশা (রা.) যখন নবিজি (ﷺ)-কে জিজ্ঞেস করলেন, এরা কি তারা যারা চুরি করে বা মদ পান করে? নবিজি (ﷺ) বললেন, 'না আয়েশা! এরা তারা যারা নামাজ পড়ে, রোজা রাখে ও সদকা করে, অথচ তারা ভয় পায় যে তাদের এই আমল হয়তো কবুল হবে না।' হজের পরও বান্দার মধ্যে এই পবিত্র খুশু ও সতর্কতা বিরাজ করা উচিত।",
            "The noble Companions of the Prophet (may Allah be pleased with them) remained deeply cautious and concerned lest their righteous deeds fall short of acceptance.\n\nIn the Holy Quran, Allah praises sincere believers, saying:\n'And those who give what they give while their hearts are fearful because they will return to their Lord.' (Surah Al-Mu'minun: 60)\nWhen mother of the believers Aishah (may Allah be pleased with her) asked whether this referred to sinners, the Prophet (ﷺ) responded: 'No, O Aishah! Rather, they are those who fast, pray, and give charity, yet fear that their deeds might not be accepted from them.' Maintaining this reverent humility after Hajj reflects genuine spiritual wisdom."
        ));

        // 5. আশা রাখা ও অধিক পরিমাণে দোয়া করা
        list.add(new HajjHistoryCardItem(
            5,
            "আশা রাখা ও অধিক পরিমাণে দোয়া করা",
            "Maintaining Hope and Abundant Supplication",
            "ভয় ও শঙ্কার পাশা-পাশী ইবাদত কবুল বিষয়ে আল্লাহর অসীম রহমতের ওপর পূর্ণ আশা রাখা...",
            "Balancing awe and fear with steadfast hope in Allah's boundless mercy, praying continuously...",
            "ভয় ও শঙ্কার পাশা-পাশী ইবাদত কবুল বিষয়ে আল্লাহর অসীম রহমতের ওপর পূর্ণ আশা (রজা) রাখা এবং বেশি বেশি দোয়া করা।\n\nমুমিনের জীবন ভয় ও আশার সমন্বয়ে গঠিত। একদিকে নিজের ত্রুটির কারণে ভয় থাকবে, অন্যদিকে পরম দয়াময় আল্লাহর ক্ষমা ও প্রতিশ্রুতির ওপর সুদৃঢ় বিশ্বাস থাকবে। হজরত ইব্রাহিম (আ.) ও হজরত ইসমাইল (আ.) যখন আল্লাহর নির্দেশে পবিত্র কাবাঘর নির্মাণ শেষ করলেন, তখন তাঁরা বিনম্র চিত্তে দোয়া করেছিলেন:\n'রাব্বানা তাকাব্বাল মিন্না, ইন্নাকা আনতাস সামীউল আলীম'—হে আমাদের প্রতিপালক! আমাদের এ আমল কবুল করুন, নিশ্চয় আপনি সর্বশ্রোতা ও সর্বজ্ঞানী। (সূরা আল-বাকারা: ১২৭)",
            "Balancing awe and humility with steadfast hope (Raja) in Allah's boundless grace, continuously supplicating for acceptance.\n\nThe life of a true believer is an equilibrium between fear and hope. While cautious of shortcomings, one places immense trust in the boundless generosity of Allah. When Prophet Ibrahim (peace be upon him) and Prophet Ismail (peace be upon him) completed building the Ka'bah, they humbled themselves in supplication:\n'Our Lord, accept this from us. Indeed, You are the All-Hearing, the All-Knowing.' (Surah Al-Baqarah: 127)"
        ));

        // 6. অধিক পরিমাণে ক্ষমা চাওয়া
        list.add(new HajjHistoryCardItem(
            6,
            "অধিক পরিমাণে ক্ষমা চাওয়া",
            "Seeking Abundant Forgiveness (Istighfar)",
            "কেননা আমল পূর্ণাঙ্গরূপে আদায়ের করার যতই চেষ্টা করা হোক না কেন, তাতে ভুলত্রুটি হওয়া স্বাভাবিক...",
            "For however diligently one strives to perform worship, human shortcomings and flaws occur...",
            "কেননা আমল পূর্ণাঙ্গরূপে আদায় করার যতই চেষ্টা করা হোক না কেন, তাতে মানবিক ত্রুটি-বিচ্যুতি ও গাফিলতি হওয়া স্বাভাবিক।\n\nএ কারণেই ইসলামে বড় বড় ইবাদতের পরেই ইস্তিগফার করার বিশেষ নির্দেশ রয়েছে। পবিত্র কুরআনে হজের বিধান বর্ণনার সমাপ্তিতে আল্লাহ বলেন:\n'অতঃপর মানুষ যেখান থেকে প্রত্যাবর্তন করে তোমরাও সেখান থেকে প্রত্যাবর্তন কর এবং আল্লাহর নিকট ক্ষমা প্রার্থনা কর। নিশ্চয়ই আল্লাহ ক্ষমাশীল, পরম দয়ালু।' (সূরা আল-বাকারা: ১৯৯)\nতাই হজের মতো মহান আমল সম্পন্ন করার পর অহংকার না করে অনবরত তাওবা ও ইস্তিগফারে রত থাকাই কবুলিয়াতের বড় নিদর্শন।",
            "No matter how diligently a human strives to fulfill acts of worship perfectly, natural human lapses, oversights, and heedlessness inevitably occur.\n\nFor this reason, Islam explicitly directs believers to make Istighfar immediately after major acts of worship. Concluding the rites of Hajj, Allah commands in the Quran:\n'Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.' (Surah Al-Baqarah: 199)\nTherefore, consistently seeking Allah's pardon rather than succumbing to complacency after Hajj is a definitive sign of divine acceptance."
        ));

        // 7. অধিক পরিমাণে নেক আমল করা
        list.add(new HajjHistoryCardItem(
            7,
            "অধিক পরিমাণে নেক আমল করা",
            "Increasing in Righteous Deeds",
            "কারণ নেক আমল একটি বৃক্ষের ন্যায় যার গোড়া মজবুত হলে তা থেকে সর্বদা নতুন সৎকাজ প্রস্ফুটিত হয়...",
            "Because righteous deed is like a tree: when its root is strong, it continuously bears virtuous fruit...",
            "কারণ নেক আমল একটি বৃক্ষের ন্যায় যার গোড়া মজবুত হলে তা থেকে সর্বদা নতুন সৎকাজের ফল উৎপন্ন হতে থাকে।\n\nইসলামি স্কলারগণ বলেন: 'একটি নেক আমলের পুরস্কার হলো তার পরে আরেকটি নেক আমল করার তাওফিক লাভ।' হজ সম্পন্ন করার পর কোনো ব্যক্তি যদি দেখে যে তার ভালো কাজ করার আগ্রহ, জামাতে নামাজ আদায়ের নিষ্ঠা, গরিব-অসহায়কে দান করার আগ্রহ এবং কুরআন তিলাওয়াতের অভ্যাস বহুলাংশে বৃদ্ধি পেয়েছে, তবে তা তার হজ কবুল হওয়ার উজ্জ্বল প্রমাণ। ধারাবাহিক সৎকাজই বান্দাকে জান্নাতের পথে অবিচল রাখে।",
            "Because a righteous deed is like a fruitful tree: when firmly rooted, it continuously yields fresh wholesome fruits of further virtue.\n\nIslamic scholars state: 'Among the rewards of a good deed is the divine enablement to perform another good deed following it.' If upon returning from Hajj a believer observes that their eagerness for voluntary worship, congregational prayers, helping the destitute, and reciting the Quran has multiplied, it is radiant proof of an accepted Hajj. Steadfast virtue keeps the servant anchored upon the path to Paradise."
        ));

        return list;
    }
}
